anatomy=function(){return `<section class="real-atlas"><header><div><span>BODY PARTS 3D · HUMAN ATLAS</span><h3>${L('Адам анатомиясының 3D атласы','3D-атлас анатомии человека','3D human anatomy atlas')}</h3><p>${L('Видеодағы ашық жобаның моделі: айналдыру, қабаттарды таңдау, жеке бұлшықеттерді көру және денені бөлшектеу.','Модель открытого проекта из видео: вращение, выбор слоёв, отдельные мышцы и разборка тела.','The open-source model from the video: rotation, layers, individual muscles and exploded anatomy.')}</p></div><button type="button" class="quiet-btn" data-atlas-full>${L('Атласты үлкейту','Развернуть атлас','Expand atlas')}</button></header><div class="real-atlas-frame"><iframe id="real-anatomy-frame" title="Human Atlas — BodyParts3D" allow="fullscreen" allowfullscreen></iframe><button class="atlas-exit" data-atlas-full>${L('Жабу','Закрыть','Close')}</button></div><footer>${L('Басқару үш тілде. Құрылым атаулары бастапқы атластағы ағылшын тілінде. Интернет қажет емес.','Управление на трёх языках. Названия структур — на английском языке исходного атласа. Интернет не требуется.','Controls in three languages. Structure names use source-atlas English. Works offline.')} <a href="https://github.com/ashemag/human-atlas" target="_blank" rel="noopener">Ashe Magalhaes / Human Atlas ↗</a></footer></section>`};
const renderWithAtlas=render;
render=function(){renderWithAtlas();const frame=document.getElementById('real-anatomy-frame');if(frame)frame.srcdoc=ATLAS_APP_HTML.replace('__LANG__',lang==='kz'?'kk':lang);};
document.addEventListener('click',async e=>{if(!e.target.closest('[data-atlas-full]'))return;try{if(document.fullscreenElement)await document.exitFullscreen();else await document.querySelector('.real-atlas-frame').requestFullscreen()}catch{document.querySelector('.real-atlas-frame').classList.toggle('atlas-expanded')}});
render();
